package com.learnspherex.payment; import java.util.*; import org.springframework.data.jpa.repository.JpaRepository; public interface PaymentRepository extends JpaRepository<Payment,Long>{List<Payment> findByStudentUserIdOrderByPaidAtDesc(Long studentUserId); boolean existsByTransactionReference(String transactionReference); List<Payment> findByInstallmentId(Long installmentId); List<Payment> findByStudentUserIdAndInstallmentId(Long studentUserId, Long installmentId);}
